mapper.select:
SELECT business_id AS id, project_id, session_id, title, status, created_at
FROM digital_team_project_conversation WHERE tenant_id = #{tenantId}
AND project_id = #{projectId} ORDER BY created_at DESC

mapper.delete:
DELETE FROM digital_team_project_conversation
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND business_id = #{taskId}

mapper.select:
SELECT business_id AS id, project_id, session_id,
coordinator_session_id, coordinator_agent_id, title, status, created_at
FROM digital_team_project_conversation WHERE tenant_id = #{tenantId}
AND project_id = #{projectId} AND business_id = #{taskId}

SELECT expert_id AS expert_id, session_id AS session_id
FROM digital_team_project_conversation_expert_session
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND conversation_id = #{taskId}

mapper.delete:
DELETE FROM digital_team_coordinator_analysis
WHERE project_id = #{projectId}
AND input_snapshot LIKE CONCAT('%conversationTaskId":"', #{taskId}, '"%')

mapper.update:
UPDATE digital_team_project_conversation SET coordinator_session_id = #{sessionId},
coordinator_agent_id = #{agentId}
WHERE business_id = #{conversationId}
AND coordinator_session_id IS NULL

mapper.select:
